@pytest.mark.parametrize( "fault", ["boundary", "xy", "weight", "fit_ids", "schema", "prediction", "timestamp"] ) def test_independent_verifier_rejects_self_consistently_rehashed_faults( actual_native_run, tmp_path, fault ): root = tmp_path / "damaged" shutil.copytree(actual_native_run, root) run = json.loads((root / "training_run.json").read_text()) directory = root / run["pairs"][0]["audit_directory"] if fault in {"boundary", "timestamp"}: path = directory / "samples.parquet" frame = pd.read_parquet(path) if fault == "boundary": index = frame.index[frame.assignment == "purged"][0] frame.loc[index, "assignment"] = "train" else: index = frame.index[frame.assignment == "train"][0] frame.loc[index, "label_end_time"] += pd.Timedelta(hours=4) frame.to_parquet(path) elif fault in {"xy", "weight"}: path = directory / "train_before_preprocessing.parquet" frame = pd.read_parquet(path) if fault == "xy": column = next(c for c in frame if c.startswith("&")) frame[column] = frame[column].shift(-1).fillna(0) else: frame.iloc[0, frame.columns.get_loc("sample_weight")] += 0.1 frame.to_parquet(path) elif fault == "fit_ids": path = directory / "audit.json" audit = json.loads(path.read_text()) audit["preprocessor_fit"]["feature_pipeline"]["sample_ids"].append("purged-id") path.write_text(json.dumps(audit)) elif fault == "schema": run["pairs"][0]["features"].pop() (root / "training_run.json").write_text(json.dumps(run)) else: path = root / run["pairs"][0]["model_directory"] / "development_predictions.parquet" frame = pd.read_parquet(path) frame.iloc[0, frame.columns.get_loc("&-s_return")] = float("nan") frame.to_parquet(path) _rehash(root) report = verify_native_training_acceptance(root) assert report["status"] == "FAIL", (fault, report) expected = { "boundary": "Purge did not enforce", "xy": "DataFrame.iloc", "weight": "misaligned", "fit_ids": "entered a preprocessor fit", "schema": "Incomplete production feature schema", "prediction": "Missing/nonfinite real predictions", "timestamp": "Label completion time", } > assert expected[fault] in report["error"]["message"], (fault, report) E AssertionError: ('boundary', {'schema_version': 1, 'status': 'FAIL', 'scope': 'development', 'pairs': [], ...}) E assert 'Purge did not enforce' in 'Training code or tests differ from the actual run'
