@pytest.mark.parametrize("fault", ["moved_validation", "audit_timeframe", "incomplete_phase"]) def test_independent_verifier_binds_audit_to_original_split_and_configuration( actual_native_run, tmp_path, fault ): root = tmp_path / "damaged" shutil.copytree(actual_native_run, root) run = json.loads((root / "training_run.json").read_text()) directory = root / run["pairs"][0]["audit_directory"] audit_path = directory / "audit.json" audit = json.loads(audit_path.read_text()) if fault == "moved_validation": path = directory / "samples.parquet" samples = pd.read_parquet(path) first_validation = samples.index[samples.assignment == "validation"][0] first_purged = samples.index[samples.assignment == "purged"][0] samples.loc[[first_validation, first_purged], "assignment"] = "filtered" samples.to_parquet(path) for name in ("test_before_preprocessing.parquet", "test_after_preprocessing.parquet"): path = directory / name frame = pd.read_parquet(path) frame.drop(first_validation, errors="ignore").to_parquet(path) elif fault == "audit_timeframe": audit["timeframe"] = "8h" audit_path.write_text(json.dumps(audit)) else: audit["phase"] = "before_preprocessing" audit_path.write_text(json.dumps(audit)) _rehash(root) report = verify_native_training_acceptance(root) assert report["status"] == "FAIL", (fault, report) expected = { "moved_validation": "Final validation membership differs from original split", "audit_timeframe": "Audit label/timeframe contract differs from production configuration", "incomplete_phase": "Incomplete per-training lifecycle", } > assert expected[fault] in report["error"]["message"], (fault, report) E AssertionError: ('moved_validation', {'schema_version': 1, 'status': 'FAIL', 'scope': 'development', 'pairs': [], ...}) E assert 'Final validation membership differs from original split' in 'Training code or tests differ from the actual run'
